const ctx = $('Input').first().json;
const msgs = $input.all().map(i => i.json).map(m => ({
  from: m.from?.value?.[0]?.address ?? m.From ?? '', subject: m.subject ?? m.Subject ?? '',
  date: m.date ?? m.internalDate ?? '', snippet: (m.textPlain ?? m.snippet ?? '').slice(0, 1500)
}));
return [{ json: { ...ctx, communications: msgs } }];

const ctx = $('Input').first().json;
const userContent = 'Client: ' + ctx.client_name + '\nLast meeting date: ' + ctx.last_meeting_date +
'\n\nCommunications since the last meeting:\n' + JSON.stringify($json.communications ?? []);
const payload = {
  model: 'claude-opus-4-8',
  max_tokens: 8000,
  system: "You are a tax-firm assistant preparing an internal briefing for a CPA before a quarterly client meeting. You are given the client's email/communication threads since the last meeting. Produce a factual digest for the preparer. Do not give advice, do not invent facts, and do not infer commitments that are not stated. If something is ambiguous, mark it as \"unclear\". Output only the JSON schema.",
  messages: [{ role: 'user', content: userContent }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["firm_commitments", "client_commitments", "open_questions", "changes", "unresolved_threads", "sentiment"], "properties": {"firm_commitments": {"type": "array", "items": {"type": "string"}}, "client_commitments": {"type": "array", "items": {"type": "string"}}, "open_questions": {"type": "array", "items": {"type": "string"}}, "changes": {"type": "array", "items": {"type": "string"}}, "unresolved_threads": {"type": "array", "items": {"type": "string"}}, "sentiment": {"type": "string", "enum": ["positive", "neutral", "concerned", "frustrated", "unclear"]}}} } }
};
return [{ json: { ...$json, payload } }];

// Structured outputs: the JSON arrives as a string in content[0].text.
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
const ctx = $('Input').first().json;
return [{ json: { ...ctx, email_digest: out } }];
